 windings.append(dict(id=key,kv_from_unverified_extract=kv,ideal_no_load_rpm_24S_full=kv*max_voltage,ideal_no_load_rpm_24S_nominal=kv*nominal_voltage,ideal_no_load_rpm_24S_at3Vcell=kv*low_voltage,theoretical_min_dc_voltage_at_200kg_rpm=rpm/kv,above_200kg_reference_at_nominal_voltage=kv*nominal_voltage>rpm,scope='Ideal no-load KV calculation only. Real loaded speed and current need winding/regulator maps. No 24S selection made.'))
