 pui=u*i;power.append(dict(id=name,reported_U_V=u,reported_I_A=i,reported_P_W=p,product_UI_W=pui,reported_P_minus_UI_W=p-pui,relative_excess_to_UI=(p-pui)/pui,voltage_implied_by_P_over_I_V=p/i,scope='Inconsistency if U and I are simultaneous DC input values. Original must clarify column assignment, current definition, actual voltage and power definition.'))
