out=dict(status='UNVERIFIED_EXTRACT_CONDITIONAL_SCREEN',source=source,reference_scope='Legacy assumed R380 three-blade aerodynamic model; mass cases are not closed D02 vehicle designs',winding_screen=windings,mass_floors=masses,power_table_flags=power,rotor_envelopes=rotors,contact_rating_screen=ratings,nova_max5000rpm_screen=[dict(mass_case_kg=x['mass_case_kg'],required_rpm=x['rpm'],exceeds_reported5000rpm=x['rpm']>5000) for x in demand],prioritized_followup='EMRAX188 LV: AC and LC original maps and CAD; compare complete cooling mass. Not a component selection or confirmed operating point.',design_release=False)
